export function craftKnowledge(serviceId){
  const specification=CRAFT_SPECIFICATIONS.find(item=>item[0]===serviceId);if(!specification)return null;
  const [id,name,category,unit,,,,scope,specificQuestion]=specification,knowledge=CRAFT_GROUP_KNOWLEDGE[category];
  return {serviceId:id,summary:`${name}: ${scope}`,questions:[...knowledge.questions,specificQuestion],risks:[...knowledge.risks],
    pricingBasis:`Bestätigte ${unit==='Std.'?'Personenstunden':unit==='m²'?'Nettoflächen in m² mit eindeutigem Aufmaß':unit==='lfm'?'Netto-Längen in laufenden Metern':'einzeln benannte Stück/Positionen'} und konkreter Leistungsumfang. Preise und Zeiten sind bearbeitbare Startannahmen; Material, Sonderaufwand, Fahrt, Rüsten, Gerätemiete und Entsorgung gesondert bestätigen.`,
    offerNotes:[...knowledge.offerNotes,'Eigene tatsächliche Preise, Qualifikation und berechtigten Betriebsumfang verwenden; keine Marktpreis-, DIN- oder Ausführungsgarantie aus dem Katalog ableiten.']};
}

function craftRoundQuantity(value){return Math.max(.001,Math.ceil((value-1e-10)*1000)/1000);}
export function materialSuggestions(serviceId,qty){
  if(typeof qty!=='number'||!Number.isFinite(qty)||qty<=0||qty>1e6)return [];
  const specification=CRAFT_SPECIFICATIONS.find(item=>item[0]===serviceId);if(!specification)return [];
  const serviceUnit=specification[3],materials=specification[9];
  return materials.map(([id,name,unit,factor,reserve,assumption,fixed=0])=>{
    const quantity=(qty*factor+fixed)*(1+reserve),wholeUnits=['Stück','Set','Kartusche','Paket'].includes(unit),suggested=wholeUnits?Math.ceil(quantity-1e-10):craftRoundQuantity(quantity);
    const reserveText=reserve?`${Math.round(reserve*100)} % ${['m²','lfm'].includes(unit)?'Beispielverschnitt / Reserve':'grobe Verbrauchs-/Bestellreserve'} bereits enthalten.`:'Keine zusätzliche Verschnitt-/Verbrauchsreserve unterstellt.';
    return {id:`${serviceId}_${id}`,name,unit,qty:suggested,note:`${assumption} Mengenschlüssel: ${factor} ${unit} je ${serviceUnit}${fixed?` plus ${fixed} ${unit} je Auftrag`:''}. ${reserveText}${wholeUnits?' Auf volle Beschaffungseinheiten aufgerundet.':' Auf 0,001 Materialeinheiten aufgerundet.'} Nur grobe Planung; Aufmaß, Produktauswahl, Herstellerverbrauch, Gebinde und Kundengestellung bestätigen. Kein technischer oder DIN-Nachweis.`};
  });
}
